```javascript
class TarefaRecorrente extends Tarefa {
  constructor(dados) {
    super(dados);
    this.frequencia = dados.frequencia ?? 'semanal';
  }
}

const regar = new TarefaRecorrente({ titulo: 'Regar as plantas', prioridade: 'alta' });
console.log(regar.rotuloDaPrioridade, regar.frequencia);
